"""Convert two-database meryl-lookup output to Rukki marker colors."""

import argparse
import os
import pathlib
import sys

SCRIPT_DIR = os.path.abspath(os.path.dirname(__file__))
sys.path.insert(0, SCRIPT_DIR)

from phase_evidence import (  # noqa: E402
    PHASE_COUNT_HEADER,
    format_phase_counts,
    marker_color,
)


def color_lookup(lookup, output, fraction, minimum_total):
    """Write Rukki columns while retaining both counts for path inference."""
    with pathlib.Path(lookup).open() as source, pathlib.Path(output).open("w") as sink:
        # Rukki reads marker columns positionally as maternal then paternal.
        # Keep that native order here; haplotype 1 is selected as paternal by
        # the downstream label files, not by reversing biological identities.
        sink.write(PHASE_COUNT_HEADER + "\n")
        for line_number, line in enumerate(source, 1):
            fields = line.split()
            if not fields or fields[0] == "Assembly":
                continue
            if len(fields) < 6:
                raise ValueError(
                    f"{lookup}:{line_number}: expected six meryl-lookup columns"
                )

            # meryl-lookup reports database intersections in columns 4 and 6.
            maternal = int(fields[3])
            paternal = int(fields[5])
            color = marker_color(maternal, paternal, fraction, minimum_total)
            sink.write(format_phase_counts(fields[0], maternal, paternal, color) + "\n")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--lookup", required=True, help="meryl-lookup output")
    parser.add_argument("--output", required=True, help="Rukki marker TSV")
    parser.add_argument("--fraction", type=float, default=0.9)
    parser.add_argument("--minimum-total", type=int, default=100)
    args = parser.parse_args()

    if not 0.5 < args.fraction <= 1.0:
        parser.error("--fraction must be greater than 0.5 and at most 1.0")
    if args.minimum_total < 0:
        parser.error("--minimum-total must be non-negative")

    color_lookup(args.lookup, args.output, args.fraction, args.minimum_total)


if __name__ == "__main__":
    main()
